                if a in v and b in v:
                    return [n(v[a]), n(v[b])]
        return None

    def points(v):
        out = []
        if isinstance(v, dict):
            v = v.values()
        if isinstance(v, (list, tuple, set)):
            for x in v:
                p = pos(x)
                if p is not None:
                    out.append(p)
                elif isinstance(x, dict):
                    for y in x.values():
                        p = pos(y)
                        if p is not None:
                            out.append(p)
        return out

    me = pos(observation.get("self_position")) or [0, 0]
    op = pos(observation.get("opponent_position")) or [10**9, 10**9]
    W = n(observation.get("grid_width", observation.get("width", 0)))
