    moves = [(1,0),(-1,0),(0,1),(0,-1),(0,0)]
    best = [0, 0]
    best_score = None
    for dx, dy in moves:
        x, y = me[0] + dx, me[1] + dy
        if W and (x < 0 or x >= W) or H and (y < 0 or y >= H):
            continue
        if (x, y) in obs:
            continue
        d = min((abs(x - r[0]) + abs(y - r[1]) for r in res), default=0)
        score = -d
        if [x, y] == op:
            score -= 3
        score -= abs(x - op[0]) + abs(y - op[1]) * 0.1
        if best_score is None or score > best_score:
            best_score = score
            best = [dx, dy]
    return best

